[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Orchard — The Best Way to Buy the Products You Love</title>
  <style>
    :root {
      --color-bg: #f5f5f7;
      --color-white: #ffffff;
      --color-text: #1d1d1f;
      --color-text-secondary: #6e6e73;
      --color-accent: #0066cc;
      --color-accent-hover: #004499;
      --color-border: #d2d2d7;
      --color-ribbon-bg: #1d1d1f;
      --font: -apple-system, "SF Pro Display", "SF Pro Text", "Helvetica Neue", Arial, sans-serif;
    }
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    html { scroll-behavior: smooth; }
    body { font-family: var(--font); background: var(--color-white); color: var(--color-text); -webkit-font-smoothing: antialiased; }
    a { color: var(--color-accent); text-decoration: none; }
    a:hover { color: var(--color-accent-hover); text-decoration: underline; }
    img { display: block; max-width: 100%; }

    /* RIBBON */
    .ribbon {
      background: var(--color-ribbon-bg);
      color: #f5f5f7;
      text-align: center;
      font-size: 13px;
      padding: 8px 16px;
      line-height: 1.4;
    }
    .ribbon a { color: #2997ff; }

    /* NAV */
    .nav {
      background: rgba(255,255,255,0.88);
      backdrop-filter: saturate(180%) blur(20px);
      -webkit-backdrop-filter: saturate(180%) blur(20px);
      border-bottom: 1px solid rgba(0,0,0,0.08);
      position: sticky;
      top: 0;
      z-index: 100;
    }
    .nav-inner {
      max-width: 1024px;
      margin: 0 auto;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 22px;
      height: 44px;
      gap: 12px;
    }
    .nav-logo {
      font-size: 20px;
      font-weight: 600;
      color: var(--color-text);
      letter-spacing: -0.5px;
      text-decoration: none;
    }
    .nav-logo:hover { text-decoration: none; color: var(--color-text); }
    .nav-links {
      display: flex;
      gap: 20px;
      list-style: none;
    }
    .nav-links a {
      font-size: 13px;
      color: var(--color-text);
      opacity: 0.85;
      white-space: nowrap;
    }
    .nav-links a:hover { opacity: 1; text-decoration: none; color: var(--color-accent); }
    .nav-actions { display: flex; gap: 16px; }
    .nav-actions a { font-size: 13px; color: var(--color-text); opacity: 0.85; }
    .nav-actions a:hover { opacity: 1; text-decoration: none; }
    @media (max-width: 768px) {
      .nav-links { display: none; }
      .nav-actions { display: none; }
    }

    /* PRODUCT GRID HERO */
    .product-grid-section {
      max-width: 1200px;
      margin: 40px auto;
      padding: 0 20px;
    }
    .product-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 12px;
    }
    @media (max-width: 768px) {
      .product-grid { grid-template-columns: 1fr; }
    }

    .product-tile {
      border-radius: 18px;
      overflow: hidden;
      position: relative;
      min-height: 360px;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: flex-end;
      padding: 36px 28px 32px;
      text-align: center;
      text-decoration: none;
      color: var(--color-text);
      transition: transform 0.2s ease;
    }
    .product-tile:hover { transform: scale(1.01); text-decoration: none; }

    .tile-phone { background: linear-gradient(170deg, #e8eaf6 0%, #c5cae9 100%); }
    .tile-laptop-neo { background: linear-gradient(170deg, #e3f2fd 0%, #bbdefb 100%); }
    .tile-tablet-pro { background: linear-gradient(170deg, #f3e5f5 0%, #e1bee7 100%); }
    .tile-laptop-pro { background: linear-gradient(170deg, #e8f5e9 0%, #c8e6c9 100%); }
    .tile-earbuds { background: linear-gradient(170deg, #fff8e1 0%, #ffecb3 100%); }
    .tile-trade { background: linear-gradient(170deg, #fce4ec 0%, #f8bbd0 100%); }

    .tile-product-visual {
      width: 140px;
      height: 140px;
      margin: 0 auto 24px;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
    }
    .tile-product-visual svg { width: 100%; height: 100%; }

    .tile-content { width: 100%; }
    .tile-name {
      font-size: 28px;
      font-weight: 700;
      letter-spacing: -0.5px;
      color: var(--color-text);
      margin-bottom: 6px;
      line-height: 1.1;
    }
    .tile-tagline {
      font-size: 15px;
      color: var(--color-text-secondary);
      margin-bottom: 20px;
      line-height: 1.4;
    }
    .tile-actions {
      display: flex;
      gap: 16px;
      justify-content: center;
      flex-wrap: wrap;
    }
    .btn-learn {
      font-size: 15px;
      color: var(--color-accent);
      font-weight: 400;
    }
    .btn-learn:hover { color: var(--color-accent-hover); }
    .btn-buy {
      font-size: 15px;
      color: var(--color-accent);
      font-weight: 400;
    }
    .btn-buy:hover { color: var(--color-accent-hover); }
    .tile-actions a { text-decoration: none; }
    .tile-actions a:hover { text-decoration: underline; }

    /* ENTERTAINMENT */
    .entertainment-section {
      background: var(--color-bg);
      padding: 80px 0 100px;
    }
    .section-header {
      text-align: center;
      margin-bottom: 40px;
      padding: 0 20px;
    }
    .section-title {
      font-size: 48px;
      font-weight: 700;
      letter-spacing: -1px;
      color: var(--color-text);
      margin-bottom: 8px;
    }
    .section-subtitle {
      font-size: 21px;
      color: var(--color-text-secondary);
      font-weight: 300;
    }
    @media (max-width: 768px) {
      .section-title { font-size: 32px; }
      .section-subtitle { font-size: 17px; }
    }

    .tabs-container {
      max-width: 1100px;
      margin: 0 auto;
      padding: 0 20px;
    }
    .tabs-nav {
      display: flex;
      gap: 0;
      margin-bottom: 32px;
      border-bottom: 1px solid var(--color-border);
      justify-content: center;
    }
    .tab-btn {
      background: none;
      border: none;
      cursor: pointer;
      font-family: var(--font);
      font-size: 15px;
      color: var(--color-text-secondary);
      padding: 12px 24px;
      position: relative;
      transition: color 0.15s;
      font-weight: 400;
      white-space: nowrap;
    }
    .tab-btn:hover { color: var(--color-text); }
    .tab-btn.active {
      color: var(--color-text);
      font-weight: 500;
    }
    .tab-btn.active::after {
      content: '';
      position: absolute;
      bottom: -1px;
      left: 0;
      right: 0;
      height: 2px;
      background: var(--color-text);
      border-radius: 1px;
    }
    .tab-panel { display: none; }
    .tab-panel.active { display: block; }

    .entertainment-cards {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 12px;
    }
    @media (max-width: 900px) { .entertainment-cards { grid-template-columns: repeat(2, 1fr); } }
    @media (max-width: 560px) { .entertainment-cards { grid-template-columns: 1fr 1fr; } }

    .ent-card {
      border-radius: 14px;
      overflow: hidden;
      background: var(--color-white);
      position: relative;
      aspect-ratio: 9/12;
      display: flex;
      flex-direction: column;
      justify-content: flex-end;
      padding: 20px 16px 16px;
      cursor: pointer;
      transition: transform 0.2s;
    }
    .ent-card:hover { transform: scale(1.02); }
    .ent-card-bg {
      position: absolute;
      inset: 0;
      background-size: cover;
      background-position: center;
    }
    .ent-card-overlay {
      position: absolute;
      inset: 0;
      background: linear-gradient(to top, rgba(0,0,0,0.7) 0%, rgba(0,0,0,0.1) 60%, transparent 100%);
    }
    .ent-card-content { position: relative; z-index: 1; color: #fff; }
    .ent-card-label {
      font-size: 11px;
      text-transform: uppercase;
      letter-spacing: 0.5px;
      opacity: 0.8;
      margin-bottom: 4px;
    }
    .ent-card-title { font-size: 15px; font-weight: 600; margin-bottom: 10px; line-height: 1.3; }
    .ent-card-cta {
      display: inline-block;
      background: rgba(255,255,255,0.2);
      border: 1px solid rgba(255,255,255,0.4);
      border-radius: 20px;
      padding: 6px 14px;
      font-size: 12px;
      color: #fff;
      backdrop-filter: blur(4px);
    }

    /* FOOTER */
    footer {
      background: var(--color-bg);
      border-top: 1px solid var(--color-border);
      padding: 40px 0 20px;
    }
    .footer-inner {
      max-width: 1100px;
      margin: 0 auto;
      padding: 0 22px;
    }
    .footer-cols {
      display: grid;
      grid-template-columns: repeat(7, 1fr);
      gap: 24px;
      padding-bottom: 32px;
      border-bottom: 1px solid var(--color-border);
    }
    @media (max-width: 1024px) { .footer-cols { grid-template-columns: repeat(4, 1fr); } }
    @media (max-width: 600px) { .footer-cols { grid-template-columns: repeat(2, 1fr); } }

    .footer-col-title {
      font-size: 12px;
      font-weight: 600;
      color: var(--color-text);
      margin-bottom: 12px;
    }
    .footer-col ul { list-style: none; }
    .footer-col ul li { margin-bottom: 8px; }
    .footer-col ul li a { font-size: 12px; color: var(--color-text-secondary); }
    .footer-col ul li a:hover { color: var(--color-text); text-decoration: none; }

    .footer-bottom {
      padding-top: 20px;
      font-size: 12px;
      color: var(--color-text-secondary);
      line-height: 1.6;
    }
    .footer-bottom p { margin-bottom: 8px; }
    .footer-legal-links {
      display: flex;
      gap: 16px;
      flex-wrap: wrap;
      margin-top: 12px;
    }
    .footer-legal-links a { font-size: 12px; color: var(--color-text-secondary); }

    /* accordion on mobile */
    @media (max-width: 600px) {
      .footer-col { overflow: hidden; }
      .footer-col-title { cursor: pointer; padding-bottom: 8px; display: flex; justify-content: space-between; align-items: center; margin-bottom: 0; }
      .footer-col-title::after { content: '+'; font-size: 16px; font-weight: 300; }
      .footer-col.open .footer-col-title::after { content: '−'; }
      .footer-col ul { max-height: 0; overflow: hidden; transition: max-height 0.3s ease; }
      .footer-col.open ul { max-height: 300px; margin-top: 8px; }
    }
  </style>
</head>
