<script>
  // Generic carousel engine
  const carousels = {};

  function initCarousel(id) {
    const track = document.getElementById('carousel-' + id);
    if (!track) return;
    carousels[id] = { pos: 0, track };
  }

  function getCardWidth(id) {
    const track = carousels[id]?.track;
    if (!track || !track.children[0]) return 232;
    const card = track.children[0];
    return card.offsetWidth + 12;
  }

  function getMaxPos(id) {
    const track = carousels[id]?.track;
    if (!track) return 0;
    const wrap = track.parentElement;
    const totalWidth = track.scrollWidth;
    const visibleWidth = wrap.offsetWidth;
    return Math.max(0, totalWidth - visibleWidth);
  }

  function moveCarousel(id, dir) {
    const state = carousels[id];
    if (!state) return;
    const step = getCardWidth(id) * 2;
    state.pos = Math.max(0, Math.min(getMaxPos(id), state.pos + dir * step));
    state.track.style.transform = `translateX(-${state.pos}px)`;
    updateArrows(id);
  }

  function updateArrows(id) {
    const state = carousels[id];
    if (!state) return;
    const btns = document.querySelectorAll(`[data-carousel="${id}"]`);
    btns.forEach(btn => {
      const dir = parseInt(btn.dataset.dir);
      if (dir === -1) btn.disabled = state.pos <= 0;
      if (dir === 1) btn.disabled = state.pos >= getMaxPos(id);
    });
  }

  ['latest','help','diff','acc','audio','savings'].forEach(id => {
    initCarousel(id);
    updateArrows(id);
  });

  document.querySelectorAll('.carousel-arrow').forEach(btn => {
    btn.addEventListener('click', () => {
      const id = btn.dataset.carousel;
      const dir = parseInt(btn.dataset.dir);
      moveCarousel(id, dir);
    });
  });

  // Footer accordion
  document.querySelectorAll('.footer-col-title').forEach(title => {
    title.addEventListener('click', () => {
      if (window.innerWidth <= 600) {
        title.closest('.footer-col').classList.toggle('open');
      }
    });
  });

  // Recalculate on resize
  window.addEventListener('resize', () => {
    ['latest','help','diff','acc','audio','savings'].forEach(id => updateArrows(id));
  });
</script>
