<script>
  const carousels = {};
  function initCarousel(id) {
    const track = document.getElementById('carousel-' + id);
    if (!track) return;
    carousels[id] = { pos: 0, track };
  }
  function getCardWidth(id) {
    const track = carousels[id]?.track;
    if (!track || !track.children[0]) return 252;
    return track.children[0].offsetWidth + 12;
  }
  function getMaxPos(id) {
    const track = carousels[id]?.track;
    if (!track) return 0;
    return Math.max(0, track.scrollWidth - track.parentElement.offsetWidth);
  }
  function moveCarousel(id, dir) {
    const state = carousels[id];
    if (!state) return;
    const step = getCardWidth(id) * 2;
    state.pos = Math.max(0, Math.min(getMaxPos(id), state.pos + dir * step));
    state.track.style.transform = `translateX(-${state.pos}px)`;
    updateArrows(id);
  }
  function updateArrows(id) {
    const state = carousels[id];
    if (!state) return;
    document.querySelectorAll(`[data-carousel="${id}"]`).forEach(btn => {
      const dir = parseInt(btn.dataset.dir);
      if (dir === -1) btn.disabled = state.pos <= 0;
      if (dir === 1) btn.disabled = state.pos >= getMaxPos(id);
    });
  }

  ['models','acc'].forEach(id => { initCarousel(id); updateArrows(id); });

  document.querySelectorAll('.carousel-arrow').forEach(btn => {
    btn.addEventListener('click', () => moveCarousel(btn.dataset.carousel, parseInt(btn.dataset.dir)));
  });

  // Section nav
  const navLinks = document.querySelectorAll('.section-nav-link');
  navLinks.forEach(link => {
    link.addEventListener('click', e => {
      e.preventDefault();
      const target = document.querySelector(link.getAttribute('href'));
      if (target) {
        const offset = 44 + 44;
        const top = target.getBoundingClientRect().top + window.scrollY - offset;
        window.scrollTo({ top, behavior: 'smooth' });
      }
      navLinks.forEach(l => l.classList.remove('active'));
      link.classList.add('active');
    });
  });

  const sections = document.querySelectorAll('section[id]');
  const observer = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        navLinks.forEach(l => {
          l.classList.toggle('active', l.getAttribute('href') === '#' + entry.target.id);
        });
      }
    });
  }, { rootMargin: '-100px 0px -60% 0px' });
  sections.forEach(s => observer.observe(s));

  document.querySelectorAll('.footer-col-title').forEach(title => {
    title.addEventListener('click', () => {
      if (window.innerWidth <= 600) title.closest('.footer-col').classList.toggle('open');
    });
  });

  window.addEventListener('resize', () => ['models','acc'].forEach(id => updateArrows(id)));
</script>
